import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Speaker panel Q and A","description":"","frontmatter":{"title":"Speaker panel Q and A","date":"2026-06-26T00:00:00.000Z","updated":"2026-06-26T00:00:00.000Z","tags":["Ceph","对象存储","性能优化","分布式存储","存储优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Speaker_panel_Q_and_A.md","filePath":"posts/2026/Speaker_panel_Q_and_A.md","lastUpdated":null}'),n={name:"posts/2026/Speaker_panel_Q_and_A.md"};function i(l,e,s,p,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-day-seattle-专家圆桌问答-会议纪要" tabindex="-1">Ceph Day Seattle 专家圆桌问答 会议纪要 <a class="header-anchor" href="#ceph-day-seattle-专家圆桌问答-会议纪要" aria-label="Permalink to &quot;Ceph Day Seattle 专家圆桌问答 会议纪要&quot;">​</a></h1><h2 id="会议概况" tabindex="-1">会议概况 <a class="header-anchor" href="#会议概况" aria-label="Permalink to &quot;会议概况&quot;">​</a></h2><p>本次会议为第二届 Ceph Day Seattle 的专家圆桌 Q&amp;A 环节，由多位 Ceph 社区资深成员和行业从业者围绕存储介质演变、Ceph 竞争力、平台支持、AI 工作负载、去重技术及市场认知等话题展开深入讨论。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-磁带存储的历史地位与未来" tabindex="-1">1. 磁带存储的历史地位与未来 <a class="header-anchor" href="#_1-磁带存储的历史地位与未来" aria-label="Permalink to &quot;1. 磁带存储的历史地位与未来&quot;">​</a></h3><p>讨论从存储技术的演变切入。与会者回顾了 SCSI 技术的历史，并指出磁带（tape）在过去数十年间多次被宣判&quot;死刑&quot;，但至今仍然顽强存活。尤其在当前 flash 和 HDD 供应链紧张的背景下，磁带作为冷数据归档的价值再次凸显。</p><p>核心观点：磁带不会消亡，它正在以云归档的形式重新回归——通过 S3 API 将数据 transition 到公有云的 Glacier 类服务，用户无需直接管理磁带库的机械细节，本质上是将磁带作为更大 object store 的后端。</p><h3 id="_2-archive-zone-与数据不可变性-immutability" tabindex="-1">2. Archive Zone 与数据不可变性（Immutability） <a class="header-anchor" href="#_2-archive-zone-与数据不可变性-immutability" aria-label="Permalink to &quot;2. Archive Zone 与数据不可变性（Immutability）&quot;">​</a></h3><p>讨论指出，社区中容易将 <strong>replica bucket replication</strong>（A→B 或 A→B→C）与 <strong>cloud transition to tape</strong>（归档）混为一谈。实际上，Ceph 的 <strong>Archive Zone</strong> 是一个独立概念，与数据 transition 无关，其核心价值在于 <strong>immutability</strong>（数据不可变性）。保持这些术语的清晰区分是社区面临的一个挑战。</p><h3 id="_3-科学界对磁带的信任" tabindex="-1">3. 科学界对磁带的信任 <a class="header-anchor" href="#_3-科学界对磁带的信任" aria-label="Permalink to &quot;3. 科学界对磁带的信任&quot;">​</a></h3><p>一位来自粒子物理领域的从业者分享了 CERN 的经验：&quot;科学家永远只信任放在架子上的磁带。&quot; 这源于物理学家经常需要回溯 1960-70 年代的实验数据，数据的长期可访问性至关重要。</p><p>会议还提到了 <strong>Vera Rubin 太空望远镜</strong>项目，预计未来五年将采集约 <strong>60 PB</strong> 的数据。数据的采集成本（包括设施建造、人力、研究投入）极其高昂，因此额外的磁带副本成本是完全必要的。</p><p>另一个案例是 <strong>Chevron（雪佛龙）</strong> 在德州的一个项目，尝试从 70 年前的磁带中恢复地震数据，成本极其高昂，且需要判断哪些数据有用、哪些应丢弃。</p><h3 id="_4-ceph-的非-linux-平台支持" tabindex="-1">4. Ceph 的非 Linux 平台支持 <a class="header-anchor" href="#_4-ceph-的非-linux-平台支持" aria-label="Permalink to &quot;4. Ceph 的非 Linux 平台支持&quot;">​</a></h3><p><strong>Windows 支持：</strong> 早期 Inktank 时代曾为 VMware 生态 kickstart 了 Windows block storage driver，代码至今存在，但实际市场需求未达预期。目前项目重心转向 <strong>NVMe over Fabric gateways</strong>。</p><p><strong>FreeBSD 支持：</strong> Python 2.7 的迁移导致 Ceph 从 FreeBSD ports 中被移除，之后未能恢复。FreeBSD 和 Lumos 生态系统用户几乎 100% 使用 <strong>ZFS</strong>，对 Ceph 的需求有限。</p><p><strong>ARM 平台：</strong> 有从业者在 Mac（Apple Silicon）上演示过 Ceph。<strong>Soft Iron</strong> 公司曾基于 ARM 制造定制硬件运行 Ceph 集群。目前 AI 基础设施大量采用 ARM 芯片（据称 80% 新数据中心使用 ARM），但 ARM 在通用服务器市场的渗透率仍然很低，属于利基市场。</p><h3 id="_5-存储介质价格与供应链" tabindex="-1">5. 存储介质价格与供应链 <a class="header-anchor" href="#_5-存储介质价格与供应链" aria-label="Permalink to &quot;5. 存储介质价格与供应链&quot;">​</a></h3><p>讨论聚焦于 flash 和 HDD 的供应链问题：</p><ul><li><strong>Gartner 预测</strong>供需平衡需要约两年，但价格不会回到从前，而是会以 2028 年的定价为基准</li><li>全球冲突对供应链的影响不容忽视——<strong>全球在建的九大新晶圆厂中有三家位于台湾</strong></li><li>光学介质（optical media）同样依赖石油生产成本（塑料成分），并非真正的替代方案</li><li><strong>QLC（四层单元闪存）</strong> 和 <strong>Flashcore Modules</strong> 有望通过提高存储密度来缓解 OSD 密度瓶颈</li></ul><h3 id="_6-去重-deduplication-技术讨论" tabindex="-1">6. 去重（Deduplication）技术讨论 <a class="header-anchor" href="#_6-去重-deduplication-技术讨论" aria-label="Permalink to &quot;6. 去重（Deduplication）技术讨论&quot;">​</a></h3><p>Ceph 中的 <strong>DDUP</strong> 长期处于实验状态（experimental），在 ceph.io 上标注为&quot;experimental&quot;。</p><p><strong>安全性顾虑：</strong> 去重与加密的结合存在安全隐患。攻击者可以通过上传已知内容来推断存储中是否已存在相同数据（例如猜测私钥内容）。这也是为什么 <strong>LUKS</strong> 默认拒绝启用 TRIM 的原因——去重和 TRIM 都会引入信息泄露向量。</p><p><strong>VDO（Virtual Data Optimizer）：</strong> Red Hat 收购相关公司后，VDO 基本消失。一位与会者指出&quot;磁盘太便宜了&quot;是去重功能未被重视的根本原因——&quot;为什么要解决一个不存在的问题？&quot;</p><p><strong>替代方案推荐：</strong> <strong>Borg Backup</strong>（borg.io）是目前最优秀的开源去重备份工具，源自 Attic 项目（一位荷兰开发者为存储音乐收藏而写）。Borg 创建一个 chunk 数据库，支持高效的 rsync 同步，但属于离线去重，不适合实时访问场景。</p><h3 id="_7-ceph-的市场认知与竞争" tabindex="-1">7. Ceph 的市场认知与竞争 <a class="header-anchor" href="#_7-ceph-的市场认知与竞争" aria-label="Permalink to &quot;7. Ceph 的市场认知与竞争&quot;">​</a></h3><p>这是讨论中最激烈的话题之一。与会者坦诚面对 Ceph 在市场中面临的认知挑战：</p><p><strong>常见误解：</strong></p><ul><li>&quot;Ceph 是一个科研项目（science project）&quot;</li><li>&quot;需要四个管理员：存储管理员、Linux 管理员、网络管理员、硬件管理员&quot;</li><li>&quot;MinIO 有数十亿下载量，Ceph 只有十万&quot;——实际上 MinIO 每个 node code 都算一次下载，并不代表有十亿集群</li><li>&quot;Red Hat/IBM 对 Ceph 有过多的商业影响力&quot;——社区与 IBM 并非一体</li></ul><p><strong>真实痛点：</strong> 单集群扩展到 <strong>数百 PB</strong> 级别存在实际挑战，主要受限于 <strong>OSD 设备密度</strong>。当前 NVMe 约 15 TB，需要约 10,000 个 OSD 才能达到百 PB 级别。QLC 和 Flashcore Modules 的发展有望缓解这一问题。</p><p><strong>Block storage 的效率问题：</strong> replica 3 模式下可用容量仅 33%，这是一个&quot;难以下咽的药丸&quot;。即将到来的 <strong>Tentacle</strong> 版本中的 <strong>fast EC（Erasure Coding）模式</strong> 将改善这一问题。</p><h3 id="_8-ai-工作负载与存储需求" tabindex="-1">8. AI 工作负载与存储需求 <a class="header-anchor" href="#_8-ai-工作负载与存储需求" aria-label="Permalink to &quot;8. AI 工作负载与存储需求&quot;">​</a></h3><p>讨论涉及 AI/ML 训练对存储的特殊要求：</p><ul><li><strong>GPU Direct</strong> 和 <strong>RDMA</strong> 是 AI 工作负载的关键需求。竞争产品（如 Vast、WeScale）已支持 GPU Direct drivers 和 RDMA 直连</li><li>Ceph 当前通过 <strong>NFS Ganesha</strong> 提供 NFS over RDMA，但 Ganesha 是用户态（user mode）实现，无法真正利用 RDMA 优势</li><li><strong>建议：</strong> 有与会者提议 Ceph Foundation 应赞助 GPU Direct 的实现，将其作为 Ceph 的核心集成能力</li><li><strong>替代方案：</strong> 微软在训练 4000 亿参数模型时，使用普通 Azure Object Storage 将数据拉取到本地节点，然后在本地 NVMe 上训练——不依赖 RDMA 存储</li></ul><h3 id="_9-rgw-federation-的现状" tabindex="-1">9. RGW Federation 的现状 <a class="header-anchor" href="#_9-rgw-federation-的现状" aria-label="Permalink to &quot;9. RGW Federation 的现状&quot;">​</a></h3><p>多位与会者确认，有大型公司正在独立编写自定义的 <strong>RGW federation layer</strong>（中间件层）。典型场景是：公司拥有 20 个集群，每个集群 30+ PB 原始容量，需要跨集群的统一命名空间。目前至少有三个不同的团队在独立开发此类解决方案。</p><p>一个常见模式：用户在 AWS S3 上养成了在单个 bucket 中存放数十亿小对象的习惯，迁移到 Ceph 后发现成本过高，需要自定义中间件来解决。</p><h3 id="_10-工具生态-rclone-与-minio-client" tabindex="-1">10. 工具生态：RClone 与 MinIO Client <a class="header-anchor" href="#_10-工具生态-rclone-与-minio-client" aria-label="Permalink to &quot;10. 工具生态：RClone 与 MinIO Client&quot;">​</a></h3><p><strong>RClone</strong> 获得了与会者的一致好评：</p><ul><li>在百万对象 PUT 测试中，RClone 击败了包括 AWS CLI 在内的所有工具</li><li>一位 IBM 客户使用 RClone 在 60 天内完成了 30-40 PB 的跨集群迁移</li><li>RClone 的参数调优能力被认为是其核心优势</li></ul><p><strong>MinIO Client (mc)</strong> 同样被推荐，特别是在递归删除非当前 S3 版本（non-current versions）方面有独特优势。与会者提醒在使用前务必先运行模拟参数（simulation parameter），再用真实数据操作。</p><p>与会者表示会根据具体场景在 RClone、mc 和其他工具之间切换使用。</p><h2 id="决定事项与后续行动" tabindex="-1">决定事项与后续行动 <a class="header-anchor" href="#决定事项与后续行动" aria-label="Permalink to &quot;决定事项与后续行动&quot;">​</a></h2><ol><li><strong>GPU Direct 支持</strong>：建议提交给 Ceph Foundation，由基金会赞助该特性的开发，作为提升 Ceph 在 AI 领域竞争力的关键举措</li><li><strong>Fast EC 模式</strong>：Tentacle 版本将引入快速 Erasure Coding，解决 replica 3 只有 33% 可用容量的痛点</li><li><strong>设备密度提升</strong>：QLC 和 Flashcore Modules 的发展将帮助 Ceph 突破单集群 OSD 数量限制</li><li><strong>RGW Federation</strong>：社区正在自发构建跨集群联邦层，未来可能需要标准化</li><li><strong>市场推广</strong>：Ceph 的营销工作组需要更加活跃，纠正&quot;科研项目&quot;等市场误解</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次圆桌讨论涵盖了从存储介质物理层到 Ceph 市场战略的广泛话题。核心共识是：Ceph 在可靠性和灵活性上具有强大优势，但在 AI 工作负载支持（GPU Direct/RDMA）、单集群超大规模扩展和市场认知方面仍需持续投入。社区自发的 RGW Federation 开发和 RClone 等工具生态的繁荣，体现了 Ceph 生态系统的活力。下一届 Ceph Day Seattle 计划在同期举行。</p>',46)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
